CREATE POLICY "user_badges_own" ON public.ziko_user_badges AS PERMISSIVE FOR ALL USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "user_gamification_own" ON public.ziko_user_gamification AS PERMISSIVE FOR ALL USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));
