CREATE POLICY "workout_programs_assigned_athlete_read" ON public.ziko_workout_programs AS PERMISSIVE FOR SELECT USING ((assigned_to_user_id = auth.uid()));
CREATE POLICY "own_sessions" ON public.ziko_workout_sessions AS PERMISSIVE FOR ALL USING ((user_id = auth.uid()));
CREATE POLICY "workout_sessions_friends_read" ON public.ziko_workout_sessions AS PERMISSIVE FOR SELECT USING ((user_id IN ( SELECT
        CASE
            WHEN (ziko_friendships.requester_id = auth.uid()) THEN ziko_friendships.addressee_id
            ELSE ziko_friendships.requester_id
        END AS requester_id
   FROM ziko_friendships
  WHERE (((auth.uid() = ziko_friendships.requester_id) OR (auth.uid() = ziko_friendships.addressee_id)) AND (ziko_friendships.status = 'accepted'::text)))));
