CREATE POLICY "xp_gifts_select" ON public.ziko_xp_gifts AS PERMISSIVE FOR SELECT USING (((auth.uid() = sender_id) OR (auth.uid() = receiver_id)));
CREATE POLICY "xp_transactions_own" ON public.ziko_xp_transactions AS PERMISSIVE FOR ALL USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));

-- ── Comments ───────────────────────────────────────────────────────────
COMMENT ON COLUMN public.ziko_ai_cost_log.source IS 'Distinguishes opex-funded autonomous AI calls (weekly_review_cron, app_open_fallback) from user-initiated, credit-gated calls (default user_chat). Added Phase 44 (ENGINE-05); backfills existing rows safely via the DEFAULT. Deliberately no CHECK constraint — Phase 47 (OPS-03) will add more autonomous sources.';
COMMENT ON TABLE public.ziko_athlete_decisions IS 'Append-only, immutable AI decision journal — rows are never updated or deleted. The only insert path is public.ziko_record_athlete_decision() (migration 20260831120200_athlete_decisions_rpc.sql).';
COMMENT ON COLUMN public.ziko_athlete_decisions.evidence IS 'Mandatory grounding payload (FOUND-02) — the schema enforces that an evidence object is present (jsonb_typeof = ''object'', no DEFAULT), but cannot enforce its truthfulness. Verifying that evidence reflects a real activity query is the calling tool executor''s responsibility, starting Phase 43.';
COMMENT ON TABLE public.ziko_athlete_goals IS 'Dedicated table (D-09) for the athlete''s broader, multi-week outcome goal — goal text, target, target_date, status. The only write path is public.ziko_record_athlete_decision()''s p_new_goal parameter (migration 20260902100200_record_athlete_decision_v2.sql). Week-scoped concrete training targets live in ziko_athlete_state.current_focus_detail (D-10) and are deliberately NOT duplicated here.';
COMMENT ON TABLE public.ziko_athlete_state IS 'Compact current-state row per athlete — one row per user_id, never a growing blob. History/audit trail lives in public.ziko_athlete_decisions. The only write path is public.ziko_record_athlete_decision() (migration 20260831120200_athlete_decisions_rpc.sql).';
COMMENT ON COLUMN public.ziko_athlete_state.readiness IS 'Top-level coaching-readiness signal, one of fragile/building/ready (D-01). Defaults to the fail-safe posture ''fragile'' (D-02) — a missing or not-yet-assessed athlete is always treated as needing the gentlest path, never assumed ready.';
COMMENT ON COLUMN public.ziko_athlete_state.rolling_summary IS 'FOUND-05 bounded-context read convention: AI callers must read this column (capped at ~500 tokens / ~2000 characters) plus the last 4 rows of public.ziko_athlete_decisions ordered by created_at DESC, and must never replay the full decisions journal. Recompaction of this column is Phase 44''s coaching-engine/context.ts, run as the last step of the weekly review.';
COMMENT ON COLUMN public.ziko_user_profiles.settings IS 'User AI and app preferences. Keys: ai_persona, ai_language, ai_coaching_style, ai_response_length, notif_prefs, hydration_goal_ml.';

